299	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
300	
301	        // 首次以错误版本请求，业务失败并随事务回滚，不占用 requestId
302	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
